<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { apiUrl } from './config'
const status=ref({}), matches=ref([]), live=ref(null), error=ref(''), action=ref(''), selected=ref(null), query=ref(''), confirmClear=ref(false), showStandings=ref(false), standings=ref(null), standingsLoading=ref(false), nowMs=ref(Date.now())
let timer
const filtered=computed(()=>matches.value.filter(m=>`${m.team_1} ${m.team_2} ${m.status}`.toLowerCase().includes(query.value.toLowerCase())))
async function refresh(){try{const [a,b]=await Promise.all([fetch(apiUrl('/api/status')),fetch(apiUrl('/api/matches'))]);if(!a.ok||!b.ok)throw Error(`HTTP ${!a.ok?a.status:b.status}`);status.value=await a.json();matches.value=await b.json();if(status.value.current_match?.id){const r=await fetch(apiUrl(`/api/matches/${status.value.current_match.id}`));live.value=r.ok?await r.json():null}else live.value=null;error.value=''}catch(e){error.value=`Сервер недоступен: ${e.message}`}}
async function control(name){action.value=name;try{const r=await fetch(apiUrl(`/api/control/${name}`),{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.detail||'Команда не выполнена');await refresh()}catch(e){error.value=`Ошибка команды: ${e.message}`}finally{action.value=''}}
async function clearObservations(){
  if(status.value.running){error.value='Остановите наблюдение перед очисткой';return}
  action.value='clear'
  try {
    const r=await fetch(apiUrl('/api/observations/clear?confirm=DELETE_ALL_OBSERVATIONS'),{method:'POST'})
    const d=await r.json()
    if(!r.ok)throw Error(d.detail||'Очистка не выполнена')
    selected.value=null;live.value=null;confirmClear.value=false
    await refresh()
  }catch(e){error.value=`Ошибка очистки: ${e.message}`}
  finally{action.value=''}
}
const oddsAge=computed(()=>{const timestamp=status.value.current_match?.odds_updated_at;return timestamp?Math.max(0,(nowMs.value-Date.parse(timestamp))/1000):Infinity})
const oddsFresh=computed(()=>oddsAge.value<=8 && status.value.current_match?.market_status==='AVAILABLE' && status.value.current_match?.odds_goal_number===status.value.current_match?.next_goal)
function liveOdd(value){return oddsFresh.value?formatOdd(value):'Ожидание актуального КФ'}
function formatOdd(value){return value===null||value===undefined?'Нет данных':String(value)}
async function toggleStandings(){
  if(showStandings.value){showStandings.value=false;return}
  standingsLoading.value=true
  try{
    const response=await fetch(apiUrl('/api/standings'),{cache:'no-store'})
    if(!response.ok)throw Error('HTTP '+response.status)
    standings.value=await response.json()
    showStandings.value=true
  }catch(e){error.value='Ошибка загрузки турнирной таблицы: '+e.message}
  finally{standingsLoading.value=false}
}
async function details(id){try{const r=await fetch(apiUrl(`/api/matches/${id}`));if(!r.ok)throw Error('Матч не найден');selected.value=await r.json()}catch(e){error.value=e.message}}
onMounted(()=>{refresh();timer=setInterval(()=>{nowMs.value=Date.now();refresh()},2000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><main class="rush"><header><div><b>RUSH MONITOR</b><h1>FC 26. 5x5 · Суперлига</h1></div><nav><a href="#control">Управление</a><a href="#live">LIVE</a><a href="#history">История</a><a href="#log">Журнал</a></nav></header>
<p v-if="error" class="error">{{error}}</p>
<section id="control" class="control"><div><span>Текущий этап</span><strong>{{status.stage||'Подключение к серверу'}}</strong></div><button :disabled="!!action||status.running" @click="control('start')">{{action==='start'?'Запуск…':'Запуск'}}</button><button class="stop" :disabled="!!action||!status.running" @click="control('stop')">{{action==='stop'?'Остановка…':'Остановка'}}</button><a :href="apiUrl('/api/export/full-history.xlsx')">Скачать Excel — все наблюдения</a><a :href="apiUrl('/api/export/all.zip')">CSV / ZIP</a><button class="standings-btn" :disabled="standingsLoading" @click="toggleStandings">{{standingsLoading?'Загрузка…':showStandings?'Скрыть таблицу':'Турнирная таблица'}}</button></section>
<section v-if="showStandings" id="standings" class="standings-panel"><div class="head"><div><h2>Турнирная таблица Rush</h2><p class="standings-note">Собственный расчёт по полностью записанным завершённым матчам; не официальная таблица 1xBet.</p></div><button class="standings-btn" @click="toggleStandings">Закрыть</button></div>
<p class="standings-count">Учтено матчей: {{standings?.matches_count??0}}</p><div class="table"><table><thead><tr><th>Место</th><th>Команда</th><th>И</th><th>В</th><th>Н</th><th>П</th><th>З</th><th>Пр</th><th>Разница</th><th>Очки</th></tr></thead><tbody>
<tr v-for="team in (standings?.table||[])" :key="team.team"><td>{{team.position}}</td><td><b>{{team.team}}</b></td><td>{{team.played}}</td><td>{{team.wins}}</td><td>{{team.draws}}</td><td>{{team.losses}}</td><td>{{team.goals_for}}</td><td>{{team.goals_against}}</td><td>{{team.goal_difference}}</td><td><b>{{team.points}}</b></td></tr>
<tr v-if="!(standings?.table||[]).length"><td colspan="10">Нет завершённых матчей с полной историей.</td></tr></tbody></table></div></section>
<section class="cards"><article><span>Backend</span><strong>{{status.running?'Наблюдение выполняется':'Остановлен'}}</strong></article><article><span>Chromium</span><strong>{{status.browser||'—'}}</strong></article><article><span>Авторизация</span><strong>{{status.auth||'—'}}</strong></article><article><span>Матчи / завершено</span><strong>{{status.matches||0}} / {{status.finished||0}}</strong></article><article><span>Зафиксировано голов</span><strong>{{status.goals||0}}</strong></article></section>
<section id="live"><div class="head"><h2>LIVE-наблюдение</h2><i :class="{on:status.running}"></i></div><template v-if="status.current_match"><div class="score"><div>{{status.current_match.team1}}</div><b>{{status.current_match.score}}</b><div>{{status.current_match.team2}}</div></div><div class="facts"><span>Тайм: <b>{{status.current_match.half}}</b></span><span>Время: <b>{{status.current_match.time||'—'}}</b></span><span>Следующий гол: <b>№{{status.current_match.next_goal}}</b></span><span>Рынок: <b>{{status.current_match.market_status||'WAITING'}}</b></span></div><div class="odds"><article><span>Следующий гол · {{status.current_match.team1}}</span><b>{{liveOdd(status.current_match.odds_1)}}</b></article><article><span>Следующий гол · {{status.current_match.team2}}</span><b>{{liveOdd(status.current_match.odds_2)}}</b></article></div><div class="table" v-if="live"><h3>Последовательность голов</h3><table><thead><tr><th>№</th><th>Тайм</th><th>Время</th><th>Забила</th><th>Счёт</th><th>КФ 1 / КФ 2</th></tr></thead><tbody><tr v-for="g in live.goals" :key="g.id"><td>{{g.goal_number}}</td><td>{{g.half}}</td><td>{{g.game_time||'—'}}</td><td>{{g.team||'Неизвестно'}}</td><td>{{g.score_after}}</td><td>{{formatOdd(g.team_1_odds)}} / {{formatOdd(g.team_2_odds)}}</td></tr><tr v-if="!live.goals.length"><td colspan="6">Голов пока нет</td></tr></tbody></table></div><small>Canvas 2D: {{status.current_match.canvas_status||'Ожидание'}} · {{oddsFresh ? ('КФ считаны ' + Math.floor(oddsAge) + ' сек. назад') : 'Актуальные коэффициенты не подтверждены'}} <template v-if="status.current_match.odds_reason">· {{status.current_match.odds_reason}}</template></small></template><p v-else class="empty">Нет активного матча. Нажмите «Запуск», затем пройдите ручную авторизацию.</p></section>
<section id="history"><div class="head"><h2>История матчей</h2><input v-model="query" placeholder="Фильтр: команда или статус"><a :href="apiUrl('/api/export/matches.csv')">CSV матчей</a><button class="clear-btn" :disabled="!!action||status.running||!matches.length" @click="confirmClear=true">Очистить список наблюдений</button></div><div v-if="confirmClear" class="clear-confirm" role="alert"><div><strong>Удалить всю историю наблюдений?</strong><p>Будут удалены матчи, голы, коэффициенты и события. Это действие нельзя отменить. Сначала скачайте Excel, если данные нужны.</p></div><button class="clear-btn" :disabled="!!action||status.running" @click="clearObservations">{{action==='clear'?'Очистка…':'Да, удалить всё'}}</button><button @click="confirmClear=false" :disabled="!!action">Отмена</button></div><div class="table"><table><thead><tr><th>Дата</th><th>Команда 1</th><th>Команда 2</th><th>1-й</th><th>2-й</th><th>Итог</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="m in filtered" :key="m.id"><td>{{m.started_at||m.created_at}}</td><td>{{m.team_1}}</td><td>{{m.team_2}}</td><td>{{m.first_half_score||'—'}}</td><td>{{m.second_half_score||'—'}}</td><td>{{m.final_score||'—'}}</td><td>{{m.status}}</td><td><button @click="details(m.id)">Детали</button></td></tr><tr v-if="!filtered.length"><td colspan="8">Записей нет</td></tr></tbody></table></div></section>
<section v-if="selected"><div class="head"><h2>Хронология: {{selected.match.team_1}} — {{selected.match.team_2}}</h2><button @click="selected=null">Закрыть</button></div><p>Таймы: {{selected.match.first_half_score||'не определён'}} / {{selected.match.second_half_score||'не определён'}} · Итог: {{selected.match.final_score||'—'}}</p><div class="table"><table><thead><tr><th>№</th><th>Тайм</th><th>Время</th><th>Забила</th><th>До</th><th>После</th><th>КФ 1 / КФ 2 до гола</th><th>Достоверность</th></tr></thead><tbody><tr v-for="g in selected.goals" :key="g.id"><td>{{g.goal_number}}</td><td>{{g.half}}</td><td>{{g.game_time||'—'}}</td><td>{{g.team||'Неизвестно'}}</td><td>{{g.score_before}}</td><td>{{g.score_after}}</td><td>{{formatOdd(g.team_1_odds)}} / {{formatOdd(g.team_2_odds)}}</td><td>{{g.sequence_confidence}}</td></tr></tbody></table></div><h3>Изменения коэффициентов</h3><div class="table"><table><thead><tr><th>Счёт</th><th>КФ 1</th><th>КФ 2</th><th>Статус</th><th>Время</th></tr></thead><tbody><tr v-for="o in selected.odds" :key="o.id"><td>{{o.score}}</td><td>{{o.team_1_odds??'—'}}</td><td>{{o.team_2_odds??'—'}}</td><td>{{o.market_status}}</td><td>{{o.captured_at}}</td></tr></tbody></table></div></section>
<section id="log"><h2>Журнал</h2><pre>{{(status.logs||[]).map(x=>`[${x.time}] ${x.message}`).join('\n')||'Событий пока нет'}}</pre></section></main></template>
<style scoped>.rush{box-sizing:border-box;min-height:100vh;width:100%;padding:24px clamp(18px,3vw,54px) 60px;background:#0c121b;color:#e8edf4;font:15px/1.45 system-ui}header,.head,.control{display:flex;align-items:center;gap:18px}header{justify-content:space-between;border-bottom:1px solid #2c4055;padding-bottom:22px}header b{color:#56e0bf;letter-spacing:.12em}h1{margin:4px 0 0;font-size:clamp(1.6rem,3vw,2.7rem)}h2{margin:0;font-size:1.2rem}nav{display:flex;gap:18px}a{color:#65d9bd;text-decoration:none;font-weight:700}.error{background:#4a272d;color:#ffc1c1;padding:12px;border-radius:8px}.control,section{margin-top:16px;padding:18px;border:1px solid #2a4058;border-radius:12px;background:#162130}.control div{margin-right:auto}.control span,.cards span,.odds span{display:block;color:#95a9c0;font-size:.78rem;text-transform:uppercase}.control strong{display:block;margin-top:4px}.control button,td button{border:0;border-radius:7px;padding:9px 15px;background:#61d8bd;color:#0d1a24;font-weight:800;cursor:pointer}.control .stop{background:#ee9999}.standings-btn{border:1px solid #4a9e9a;border-radius:7px;padding:10px 14px;color:#b4ffea;background:#17413e;font-weight:750;cursor:pointer}.standings-btn:disabled{opacity:.5}.standings-panel{border-color:#2b6664}.standings-note{margin:5px 0;color:#a6b9c8;font-size:.85rem}.standings-count{color:#64dabe;font-weight:700}.clear-btn{border:1px solid #a65d66;border-radius:7px;padding:9px 12px;color:#ffd2d2;background:#552630;font-weight:750;cursor:pointer}.clear-btn:disabled{opacity:.45;cursor:not-allowed}.clear-confirm{display:flex;align-items:center;flex-wrap:wrap;gap:12px;border:1px solid #a65d66;background:#331f29;padding:16px;border-radius:9px;margin-top:14px}.clear-confirm div{flex:1;min-width:250px}.clear-confirm p{margin:6px 0 0;color:#e3b8bf}.clear-confirm button{padding:9px 14px;border-radius:7px;border:1px solid #9e626b;cursor:pointer;background:#41252e;color:#fff}.head{flex-wrap:wrap}.control button:disabled{opacity:.45}.cards{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:14px;margin-top:16px}.cards article{padding:16px;border:1px solid #294058;border-radius:10px;background:#152435}.cards strong{display:block;margin-top:7px;font-size:1rem}.head input{margin-left:auto;background:#0e1722;border:1px solid #38516c;padding:9px;border-radius:7px;color:#fff}.head i{width:10px;height:10px;border-radius:50%;background:#748090}.head i.on{background:#50d7a9;box-shadow:0 0 12px #50d7a9}.score{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;text-align:center;margin:25px 0;font-size:1.2rem}.score b{font-size:clamp(2.6rem,7vw,5rem);padding:0 8vw}.facts{display:flex;gap:28px;justify-content:center}.odds{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}.odds article{padding:16px;border:1px solid #31526b;border-radius:9px;background:#102131}.odds b{display:block;margin-top:5px;font-size:1.8rem;color:#65d9bd}.empty{color:#aab8c9}.table{overflow:auto;margin-top:14px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:11px;border-top:1px solid #2a3e54}th{font-size:.74rem;text-transform:uppercase;color:#9aafc5}pre{max-height:310px;overflow:auto;white-space:pre-wrap;background:#0d1721;padding:14px;border-radius:8px}@media(max-width:800px){.rush{padding:16px}header{align-items:start;flex-direction:column}nav{flex-wrap:wrap}.cards,.odds{grid-template-columns:repeat(2,1fr)}.control{flex-wrap:wrap}.control div{width:100%}.head{flex-wrap:wrap}.head input{margin-left:0}.facts{flex-wrap:wrap;justify-content:start}.score{font-size:1rem}.score b{padding:0 12px}}</style>
